mapper.select:
SELECT * FROM dimension_commission_plan WHERE artist_id = #{artistId}
AND status = 1
ORDER BY id DESC

mapper.update:
UPDATE dimension_commission_plan
SET status = #{status}
WHERE id = #{planId} AND artist_id = #{artistId}

UPDATE dimension_commission_order
SET delivery_preview = #{url}, status = 2, update_time = NOW()
WHERE id = #{orderId}

UPDATE dimension_commission_order
SET delivery_final = #{url}, status = 2, update_time = NOW()
WHERE id = #{orderId}
